def main(docket: dict):
    net_mass_tonnes = docket['net_mass_kg'] / 1000.0
    co2_tonnes = round(net_mass_tonnes * 2.56, 3)
    tariff_eur = round(co2_tonnes * 72.50, 2)
    return {'embedded_co2_t': co2_tonnes, 'tariff_payable_eur': tariff_eur, 'status': 'AUDITED'}

def main(docket: dict, audit: dict):
    cert_id = f"CBAM-CERT-{docket['docket_id']}-2026"
    return {'certificate_id': cert_id, 'docket_id': docket['docket_id'], 'tariff_eur': audit['tariff_payable_eur'], 'compliance': 'PASSED'}
